___INFO___

{
  "type": "MACRO",
  "id": "cvt_temp_public_id",
  "version": 1,
  "securityGroups": [],
  "displayName": "Google Tag Geo Data",
  "categories": [
    "UTILITY"
  ],
  "description": "Returns country, region or DMA flag from the Google tag\u0027s built-in IP geolocation cache. Sandboxed JS only - no Custom HTML/JS.",
  "containerContexts": [
    "WEB"
  ]
}


___TEMPLATE_PARAMETERS___

[
  {
    "type": "TEXT",
    "name": "geoGetter",
    "displayName": "Geo getter (JavaScript Variable returning the function)",
    "defaultValue": "{{Google Tag Geo Getter}}"
  },
  {
    "type": "SELECT",
    "name": "output",
    "displayName": "Value to return",
    "macroSelectType": "NONE",
    "selectItems": [
      {
        "value": "country",
        "displayValue": "Country (ISO 3166-1, e.g. ES)"
      },
      {
        "value": "region",
        "displayValue": "Region (ISO 3166-2, e.g. ES-MC)"
      },
      {
        "value": "dma",
        "displayValue": "Is DMA region (true/false)"
      },
      {
        "value": "json",
        "displayValue": "All values as JSON string"
      }
    ],
    "simpleValueType": true,
    "defaultValue": "country"
  }
]


___SANDBOXED_JS_FOR_WEB_TEMPLATE___

const JSON = require('JSON');
const getType = require('getType');

// data.geoGetter is the built-in "JavaScript Variable"
// google_tag_data.xcd.ip_geo_data_cache.get - GTM resolves it to the function
// itself. No callInWindow / copyFromWindow / permissions required.
const readGeo = () => {
  const getter = data.geoGetter;
  if (getType(getter) !== 'function') return undefined;
  const raw = getter();
  if (!raw) return undefined;
  const geo = getType(raw) === 'string' ? JSON.parse(raw) : raw;
  if (!geo) return undefined;
  const dma = geo['6'];
  return {
    country: geo['0'],
    region: geo['1'],
    isDma: dma === undefined ? undefined : (dma === true || dma === 1 || dma === 'true')
  };
};

const geo = readGeo();
if (!geo) return undefined;

const out = data.output;
if (out === 'country') return geo.country;
if (out === 'region') return geo.region;
if (out === 'dma') return geo.isDma;
if (out === 'json') return JSON.stringify(geo);
return undefined;


___TESTS___

scenarios:
- name: Country
  code: |-
    let r = runCode({output: 'country', geoGetter: () => '{"0":"ES","1":"ES-MC","6":false}'});
    assertThat(r).isEqualTo('ES');
- name: Region
  code: |-
    let r = runCode({output: 'region', geoGetter: () => '{"0":"JP","1":"JP-13","6":false}'});
    assertThat(r).isEqualTo('JP-13');
- name: DMA true
  code: |-
    let r = runCode({output: 'dma', geoGetter: () => '{"0":"DE","1":"DE-BE","6":true}'});
    assertThat(r).isEqualTo(true);
- name: Cache unavailable
  code: |-
    let r = runCode({output: 'country', geoGetter: () => undefined});
    assertThat(r).isUndefined();
- name: Getter missing (Google tag not loaded)
  code: |-
    let r = runCode({output: 'country', geoGetter: undefined});
    assertThat(r).isUndefined();
- name: Invalid JSON
  code: |-
    let r = runCode({output: 'country', geoGetter: () => 'not json'});
    assertThat(r).isUndefined();


___NOTES___

Uses undocumented Google tag internals (window.google_tag_data.xcd.ip_geo_data_cache). Indices: 0=country, 1=region, 6=DMA flag. May change without notice. Value is only available after the Google tag has loaded. Requires the built-in JavaScript Variable google_tag_data.xcd.ip_geo_data_cache.get as input.

